// inwards: opencode plugin (written by inwards init 0.1.0; run it again to update this file)
// Runs `inwards hook claude-code` on OpenCode's plugin events, so the config
// guard, the per-edit check and the Stop gate work as they do in Claude Code.
// It holds this machine's path to Inwards and is in .gitignore.
import { createHash } from "node:crypto";
import { readFileSync, readlinkSync, realpathSync } from "node:fs";
import { basename, dirname, isAbsolute, join, resolve, sep } from "node:path";
import { fileURLToPath } from "node:url";

const INWARDS = ["/tmp/inwards-eval-bin-LvES21/inwards-linux-arm64"];
/** The project init wrote this plugin into, whichever directory OpenCode runs in. */
const PROJECT = dirname(dirname(dirname(fileURLToPath(import.meta.url))));
/** This file's hash as OpenCode loaded it: the Stop gate reports a plugin changed since. */
const SELF = createHash("sha256")
  .update(readFileSync(fileURLToPath(import.meta.url)))
  .digest("hex");
/** OpenCode tools the hooks see, under the Claude Code names the hook knows. */
const TOOLS = { edit: "Edit", write: "Write", bash: "Bash" };
/** Inwards' own files and this plugin, either separator, any case. */
const PROTECTED = /(^|[\\/])(\.opencode[\\/]|opencode\.jsonc?$|\.inwards[\\/]|inwards-baseline\.json$)/iu;

display.text:
// inwards: opencode plugin (written by inwards init 0.1.0; run it again to update this file)
// Runs `inwards hook claude-code` on OpenCode's plugin events, so the config
// guard, the per-edit check and the Stop gate work as they do in Claude Code.
// It holds this machine's path to Inwards and is in .gitignore.
import { createHash } from "node:crypto";
import { readFileSync, readlinkSync, realpathSync } from "node:fs";
import { basename, dirname, isAbsolute, join, resolve, sep } from "node:path";
import { fileURLToPath } from "node:url";

const INWARDS = ["/tmp/inwards-eval-bin-LvES21/inwards-linux-arm64"];
/** The project init wrote this plugin into, whichever directory OpenCode runs in. */
const PROJECT = dirname(dirname(dirname(fileURLToPath(import.meta.url))));
/** This file's hash as OpenCode loaded it: the Stop gate reports a plugin changed since. */
const SELF = createHash("sha256")
  .update(readFileSync(fileURLToPath(import.meta.url)))
  .digest("hex");
/** OpenCode tools the hooks see, under the Claude Code names the hook knows. */
const TOOLS = { edit: "Edit", write: "Write", bash: "Bash" };
/** Inwards' own files and this plugin, either separator, any case. */
const PROTECTED = /(^|[\\/])(\.opencode[\\/]|opencode\.jsonc?$|\.inwards[\\/]|inwards-baseline\.json$)/iu;
const CONFIG = /(^|[\\/])pyproject\.toml$/iu;
/** A command that names one of those files, or the config. */
const MENTIONS = /pyproject\.toml|\.opencode|opencode\.jsonc?|\.inwards|inwards-baseline/iu;
/**
 * A patch header, read at least as leniently as OpenCode reads it. OpenCode
 * splits a patch on "\n" only, so the path runs to that: a "\r" or a Unicode
 * line separator inside it is part of the path, and it is trimmed as
 * OpenCode trims it.
 */
const PATCH_FILE = /^\s*\*\*\*\s*(?:(?:Add|Update|Delete)\s+File|Move\s+to)\s*:(?<path>[^\n]*)$/iu;
/** Inwards' own files and this plugin, by where they are in the project; links to them count too. */
const OWN_FILES = [".opencode", ".inwards", "inwards-baseline.json", "opencode.json", "opencode.jsonc"];
/** Marks the messages the plugin sends, so they don't count as the user's. */
const OWN = "(sent by the Inwards plugin, not the user)";
const STOP_PREFACE = `Inwards Stop gate ${OWN}: the turn can't end yet. Fix what follows, then finish your turn.\n\n`;
const NOTE_PREFACE = `Inwards ${OWN}: `;
/** How many links to follow by hand before giving up on a path. */
const MAX_LINKS = 40;
/** How long one hook run may take, as Claude Code's default hook timeout. */
const HOOK_TIMEOUT_MS = 60000;

/**
 * Runs the hook with one payload, in the project init wrote the plugin into.
 *
 * @param payload - a hook payload, as Claude Code would send it.
 * @returns the exit code and both output streams; code -1 when Inwards couldn't start or was stopped.
 */
async function hook(payload) {
  try {
    const proc = Bun.spawn([...INWARDS, "hook", "claude-code"], {
      cwd: PROJECT,
      stdin: new TextEncoder().encode(JSON.stringify({ cwd: PROJECT, ...payload })),
      stdout: "pipe",
      stderr: "pipe",
      timeout: HOOK_TIMEOUT_MS,
      env: {
        ...process.env,
        CLAUDE_PROJECT_DIR: PROJECT,
        INWARDS_HOOK_HOST: "opencode",
        INWARDS_PLUGIN_SHA256: SELF,
      },
    });
    const [stdout, stderr, code] = await Promise.all([
      new Response(proc.stdout).text(),
      new Response(proc.stderr).text(),
      proc.exited,
    ]);
    return proc.signalCode
      ? { code: -1, stdout, stderr: `inwards: stopped (${proc.signalCode}); a hook run may take ${HOOK_TIMEOUT_MS / 1000} s` }
      : { code, stdout, stderr };
  } catch (err) {
    return { code: -1, stdout: "", stderr: `inwards: ${String(err)}` };
  }
}

/**
 * Tells whether the hook failed instead of answering: it couldn't start, or
 * exited with neither 0 nor 2.
 *
 * @param result - what `hook` returned.
 * @returns true when nothing was checked.
 */
function broken(result) {
  return result.code !== 0 && result.code !== 2;
}

/**
 * Reads a field of the hook's JSON output.
 *
 * @param stdout - the hook's output.
 * @returns the parsed object, or an empty one.
 */
function output(stdout) {
  try {
    return JSON.parse(stdout) ?? {};
  } catch {
    return {};
  }
}

/**
 * Reads the reason out of a PreToolUse deny, if the hook denied.
 *
 * @param stdout - the hook's output.
 * @returns the reason (a default when the hook gave none), or undefined when the call may go ahead.
 */
function denial(stdout) {
  const decision = output(stdout).hookSpecificOutput;
  if (decision?.permissionDecision !== "deny") {
    return undefined;
  }
  return decision.permissionDecisionReason || "Inwards refused this call.";
}

/**
 * Resolves links in a path, a dangling one included, so an alias can't hide
 * a protected file. A path that doesn't exist yet resolves through its
 * nearest existing directory.
 *
 * @param path - an absolute path.
 * @param depth - links followed so far.
 * @returns the path with every link resolved that can be.
 */
function real(path, depth = 0) {
  try {
    return realpathSync(path);
  } catch {
    // missing, or a dangling link: go on by hand
  }
  if (depth > MAX_LINKS) {
    return path;
  }
  try {
    return real(resolve(dirname(path), readlinkSync(path)), depth + 1);
  } catch {
    // not a link
  }
  const parent = dirname(path);
  return parent === path ? path : join(real(parent, depth + 1), basename(path));
}

/**
 * Tells whether a path, as written or once its links are resolved, matches.
 *
 * @param pattern - PROTECTED or CONFIG.
 * @param path - an absolute path.
 * @returns true when either spelling matches.
 */
function names(pattern, path) {
  const p = String(path ?? "");
  return pattern.test(p) || pattern.test(real(p));
}

/**
 * Tells whether a path is, or lies inside, one of the project's own files
 * once links on both sides are resolved: \`settings.toml\` when
 * \`pyproject.toml\` links to it, say.
 *
 * @param path - an absolute path.
 * @param names - files of the project, relative to it.
 * @returns true when the path resolves into one of them.
 */
function resolvesTo(path, names) {
  const target = real(String(path ?? ""));
  return names.some((name) => {
    const own = real(join(PROJECT, name));
    return target === own || target.startsWith(own + sep);
  });
}

/**
 * Tells whether a path is Inwards' own: the plugin, the state, the baseline or OpenCode's config.
 *
 * @param path - an absolute path.
 * @returns true when no tool may change it without the user.
 */
function inwardsOwn(path) {
  return names(PROTECTED, path) || resolvesTo(path, OWN_FILES);
}

/**
 * Tells whether a path is a pyproject.toml, or a config reached through a
 * link: the file a \`pyproject.toml\` in its directory, or any directory
 * above it in the project, links to.
 *
 * @param path - an absolute path.
 * @returns true when the config guard must see the change.
 */
function configFile(path) {
  if (names(CONFIG, path) || resolvesTo(path, ["pyproject.toml"])) {
    return true;
  }
  const written = resolve(String(path ?? ""));
  const target = real(written);
  // The directories above the path as written, and above where it really is.
  return [
    [dirname(written), resolve(PROJECT)],
    [dirname(target), real(PROJECT)],
  ].some(([start, top]) => linksFromAbove(start, top, target));
}

/**
 * Tells whether a pyproject.toml in a directory, or in one above it up to
 * the project, links to a file.
 *
 * @param start - the first directory to look in.
 * @param top - the project directory, where the search stops.
 * @param target - the file's real path.
 * @returns true when one of them resolves to it.
 */
function linksFromAbove(start, top, target) {
  for (let dir = start; dir === top || dir.startsWith(top + sep); dir = dirname(dir)) {
    if (real(join(dir, "pyproject.toml")) === target) {
      return true;
    }
    if (dir === top) {
      break;
    }
  }
  return false;
}

/**
 * Makes a tool's path absolute, against the directory OpenCode runs in.
 *
 * @param directory - OpenCode's working directory.
 * @param path - the path the tool got.
 * @returns the absolute path, or the value as is when it isn't a string.
 */
function absolute(directory, path) {
  return typeof path === "string" && !isAbsolute(path) ? resolve(directory, path) : path;
}

/**
 * Maps an OpenCode tool's arguments to what the Claude Code tool of the same kind takes.
 *
 * @param tool - the OpenCode tool.
 * @param args - its arguments.
 * @param directory - OpenCode's working directory, for relative paths.
 * @returns the tool input the hook reads.
 */
function toolInput(tool, args, directory) {
  if (tool === "edit") {
    return {
      file_path: absolute(directory, args.filePath),
      old_string: args.oldString,
      new_string: args.newString,
      replace_all: args.replaceAll === true,
    };
  }
  if (tool === "write") {
    return { file_path: absolute(directory, args.filePath), content: args.content };
  }
  return { command: args.command };
}

/**
 * Tells whether OpenCode would change something other than the exact match
 * of an edit's oldString. Without exactly one exact match (or one at all,
 * with replaceAll) OpenCode tries looser matches: trimmed lines, collapsed
 * whitespace, a leading BOM dropped. The config guard simulates the exact,
 * normalised match only, so the two could change different lines. The
 * guard also drops a leading BOM from both strings and OpenCode doesn't, so
 * such an edit is never simulated as written.
 *
 * @param input - the edit's tool input, as the hook reads it.
 * @returns true when the edit's target is up to OpenCode's fallbacks.
 */
function inexact(input) {
  const from = String(input.old_string ?? "").replaceAll("\r\n", "\n");
  if (from.startsWith("\uFEFF") || String(input.new_string ?? "").startsWith("\uFEFF")) {
    return true;
  }
  if (from === "") {
    return false; // creates a file, which the guard simulates
  }
  let text;
  try {
    // As OpenCode reads it: the BOM dropped, then the text matched as is.
    text = readFileSync(input.file_path, "utf8").replace(/^\uFEFF/u, "").replaceAll("\r\n", "\n");
  } catch {
    return false; // a missing file: the guard denies what it can't simulate
  }
  const first = text.indexOf(from);
  if (first === -1) {
    return true;
  }
  return !input.replace_all && text.lastIndexOf(from) !== first;
}

/**
 * Lists the files an apply_patch call touches.
 *
 * @param text - the patch.
 * @param directory - OpenCode's working directory.
 * @returns absolute paths.
 */
function patchedFiles(text, directory) {
  return String(text ?? "")
    .split("\n")
    .map((line) => PATCH_FILE.exec(line)?.groups?.path?.trim() ?? "")
    .filter((path) => path !== "")
    .map((path) => absolute(directory, path));
}

/**
 * Tells whether a tool call reaches the config or Inwards' own files.
 *
 * @param tool - the OpenCode tool.
 * @param input - its tool input, as the hook reads it.
 * @returns true when a failed hook must not let it through.
 */
function touchesRules(tool, input) {
  if (tool === "bash") {
    return MENTIONS.test(String(input.command ?? ""));
  }
  return configFile(input.file_path) || inwardsOwn(input.file_path);
}

/**
 * Tells whether a message is one the plugin sent, and which kind.
 *
 * @param parts - the message's parts.
 * @returns "stop" for the Stop gate's, "note" for another, or undefined for the user's.
 */
function ownMessage(parts) {
  const text = (parts ?? []).map((p) => (typeof p?.text === "string" ? p.text : "")).join("");
  if (text.startsWith(STOP_PREFACE)) {
    return "stop";
  }
  return text.startsWith(NOTE_PREFACE) ? "note" : undefined;
}

/** How many times a session lookup, or the Stop gate's message, is tried before giving up for now. */
const ATTEMPTS = 3;

export const Inwards = async ({ client, directory }) => {
  /**
   * What the plugin knows about each top-level session:
   * - whether the Stop gate sent it back to work, whether that message is still
   *   on its way or couldn't be sent, which turn it is (a user's message or
   *   the gate's starts one), and which turn the gate is answering;
   * - how many messages the user sent, and how many idles came: only the
   *   latest idle, from after the user's latest message, runs the gate;
   * - whether a turn is running, how many started (a busy status each), and
   *   how many had when the gate began its run, and whether one started by a message
   *   ended unchecked: an idle after a shell command, a compaction or an
   *   abort runs no gate;
   * - the agent, model and variant the user picked;
   * - how it started, and the queue that runs its Stop checks one at a time.
   */
  const sessions = new Map();
  /** A subagent's session, by the top-level session it works for. */
  const parents = new Map();
  /** Sessions a message went to while their lookup failed: their next idle runs the gate. */
  const unresolved = new Set();
  const state = (id) => {
    if (!sessions.has(id)) {
      sessions.set(id, {
        continued: false,
        pending: false,
        activity: 0,
        checked: 0,
        awaiting: false,
        turn: 0,
        running: undefined,
        unsent: undefined,
        generation: 0,
        idles: 0,
        busy: false,
        starting: undefined,
        chosen: {},
        queue: Promise.resolve(),
      });
    }
    return sessions.get(id);
  };

  /**
   * Sends a message into a session. The SDK reports a refused request in its
   * result; a thrown error (the connection dropped) leaves unknown whether
   * OpenCode took the message.
   *
   * @param id - the session.
   * @param body - the prompt body, without the session's chosen agent and model.
   * @returns "sent", "refused", or "unknown" when the request threw.
   */
  const send = async (id, body) => {
    try {
      const result = await client.session.promptAsync({ path: { id }, body: { ...state(id).chosen, ...body } });
      return result?.error ? "refused" : "sent";
    } catch {
      return "unknown";
    }
  };

  /**
   * Finds the top-level session a session works for. A subagent's session
   * created before OpenCode started is looked up; a failed lookup is tried again next time.
   *
   * @param id - any session id.
   * @returns the id of its top-level session, or undefined while a lookup fails.
   */
  const root = async (id) => {
    if (parents.has(id)) {
      return parents.get(id);
    }
    if (sessions.has(id)) {
      return id;
    }
    let found;
    for (let attempt = 0; attempt < ATTEMPTS && !found; attempt += 1) {
      try {
        const answer = await client.session.get({ path: { id } });
        found = answer?.error ? undefined : answer?.data;
      } catch {
        found = undefined;
      }
    }
    if (!found) {
      return undefined;
    }
    const parentID = found.parentID;
    if (parentID) {
      const top = await root(parentID);
      if (top !== undefined) {
        parents.set(id, top);
      }
      return top;
    }
    state(id);
    return id;
  };

  /**
   * Records how a top-level session starts, once; every hook of the session
   * waits for it. A session OpenCode resumed gets a resume, which only logs itself.
   *
   * @param id - a top-level session.
   * @param source - "startup" for a new session, "resume" otherwise.
   * @returns when the record is written.
   */
  const start = (id, source) => {
    const s = state(id);
    s.starting ??= (async () => {
      const result = await hook({ session_id: id, hook_event_name: "SessionStart", source });
      const context = output(result.stdout).hookSpecificOutput?.additionalContext;
      if (context) {
        await note(id, context);
      }
    })();
    return s.starting;
  };

  /**
   * Adds a message to a session for the model and the user to read, without
   * starting a turn. A turn that is running may still read it.
   *
   * @param id - the session.
   * @param text - what to say.
   */
  const note = async (id, text) => {
    await send(id, { noReply: true, parts: [{ type: "text", text: NOTE_PREFACE + text }] });
  };

  /**
   * Tells whether an idle still stands: the latest one, after the user's
   * latest message, with no turn running and no message from the gate on its way.
   *
   * @param s - the session's state.
   * @param idle - what the idle saw: its number and the user's message count.
   * @returns true when the gate may run, or act on its result.
   */
  const current = (s, idle) =>
    idle.number === s.idles && idle.generation === s.generation && !s.busy && !s.awaiting;

  /**
   * Runs the Stop gate for a top-level session that went idle. OpenCode can't
   * refuse the end of a turn, so a block starts another one with the gate's
   * reasons, as the agent the user picked.
   *
   * @param id - the session.
   * @param idle - the idle's number and the user's message count when it came.
   */
  const stop = async (id, idle) => {
    const s = state(id);
    if (!current(s, idle)) {
      return; // a later idle, a message or a turn made this one stale
    }
    if (!s.pending && s.unsent === undefined) {
      return; // no message started a turn since the last check: a shell command, a compaction or an abort
    }
    s.pending = false;
    s.running = s.turn;
    s.checked = s.activity;
    try {
      await answer(id, s, idle);
    } finally {
      s.running = undefined;
    }
  };

  /**
   * Runs the gate for an idle that stands and passes on what it says. A gate
   * message that couldn't be sent is sent again instead: the gate already
   * counted that attempt.
   *
   * @param id - the session.
   * @param s - its state.
   * @param idle - the idle's number and the user's message count when it came.
   */
  const answer = async (id, s, idle) => {
    if (s.unsent !== undefined) {
      await deliver(id, s, s.unsent);
      return;
    }
    const result = await hook({ session_id: id, hook_event_name: "Stop", stop_hook_active: s.continued });
    // The gate has counted this attempt, so a later idle doesn't make the result stale;
    // a message from the user, or a turn that started, does. A turn with no
    // message (a shell command) leaves this one's check to the next idle.
    if (idle.generation !== s.generation || s.busy || s.awaiting || s.activity !== s.checked) {
      if (idle.generation === s.generation) {
        s.pending = true;
      }
      return;
    }
    if (result.code === 2) {
      s.continued = true;
      await deliver(id, s, STOP_PREFACE + result.stderr);
      return;
    }
    s.continued = false;
    const message = broken(result)
      ? `the Stop gate couldn't run: ${result.stderr.trim()}`
      : output(result.stdout).systemMessage;
    if (message) {
      await note(id, message);
    }
  };

  /**
   * Sends the gate's message, which starts another turn. A refused request
   * is tried again, up to ATTEMPTS times; one that still fails, or may have
   * got through, is kept for the next idle, and dropped if it arrives.
   *
   * @param id - the session.
   * @param s - its state.
   * @param text - the message.
   */
  const deliver = async (id, s, text) => {
    const { generation, turn } = s;
    s.awaiting = true;
    for (let attempt = 0; attempt < ATTEMPTS; attempt += 1) {
      const outcome = await send(id, { parts: [{ type: "text", text }] });
      if (outcome === "sent") {
        s.unsent = undefined;
        return;
      }
      // The user moved on while the request ran, or OpenCode took the message
      // anyway (a new turn): sending it again would be stale or a duplicate.
      if (generation !== s.generation || turn !== s.turn) {
        return;
      }
      if (outcome === "unknown") {
        break; // trying again at once could send it twice
      }
    }
    s.awaiting = false;
    s.unsent = text;
  };

  return {
    event: async ({ event }) => {
      if (event.type === "session.created") {
        const { id, parentID } = event.properties.info;
        if (parentID) {
          const top = await root(parentID);
          if (top !== undefined) {
            parents.set(id, top);
          }
          return;
        }
        await start(id, "startup");
      } else if (event.type === "session.status") {
        const id = event.properties.sessionID;
        if (sessions.has(id)) {
          // A retry is a turn still running.
          const s = state(id);
          s.busy = (event.properties.status?.type ?? "idle") !== "idle";
          s.activity += s.busy ? 1 : 0;
        }
      } else if (event.type === "session.error") {
        const aborted = event.properties.error?.name === "MessageAbortedError";
        if (aborted) {
          unresolved.delete(event.properties.sessionID);
        }
        const s = sessions.get(event.properties.sessionID);
        if (s !== undefined) {
          s.awaiting = false; // a message that failed after it was accepted
          if (aborted) {
            s.pending = false; // the user stopped the turn: the gate doesn't send the agent back
          }
        }
      } else if (event.type === "session.idle") {
        const id = event.properties.sessionID;
        // Before anything waits: later idles and messages make this one stale.
        const known = sessions.get(id);
        if (known !== undefined && known.running === known.turn && known.activity === known.checked) {
          return; // the gate is already answering this turn's idle; after a shell command, this idle checks again
        }
        const seen = known ? { number: ++known.idles, generation: known.generation } : undefined;
        if (known) {
          known.busy = false; // now, so activity seen while this handler waits isn't overwritten
        }
        if ((await root(id)) !== id) {
          return; // a subagent, or not known yet: the gate runs for the session it works for
        }
        await start(id, "resume");
        const s = state(id);
        if (unresolved.delete(id)) {
          s.pending = true;
        }
        const idle = seen ?? { number: ++s.idles, generation: s.generation };
        s.queue = s.queue.then(() => stop(id, idle)).catch(() => undefined);
        await s.queue;
      }
    },
    "chat.message": async (input, out) => {
      const id = await root(input.sessionID);
      if (id === undefined) {
        unresolved.add(input.sessionID); // the lookup failed: its idle runs the gate once it succeeds
        return;
      }
      if (id !== input.sessionID) {
        return; // a prompt to a subagent is part of its parent's turn
      }
      const s = state(id);
      const own = ownMessage(out?.parts);
      if (own === "stop") {
        // The gate's message arrived: the continued turn begins, and idles queued before it are stale.
        s.awaiting = false;
        s.busy = true;
        s.turn += 1;
